def merge_intervals(intervals):
    """Merge overlapping intervals (inclusive) and return them sorted by start;
    touching intervals like (1, 2) and (2, 3) are merged into one.
    """
    if not intervals:
        return []
    intervals = sorted(intervals)
    merged = [intervals[0]]
    for start, end in intervals[1:]:
        last_start, last_end = merged[-1]
        if start < last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged
```

