```python
def retry(times):
    """Декоратор: вызывает функцию не больше `times` раз суммарно.

    Если ни одна попытка не вернула значение без исключения,
    наружу поднимается исключение из последней попытки.
    """
    def deco(fn):
        def wrapper(*args, **kwargs):
            last_exc = None
            for _ in range(times + 1):
                try:
                    return fn(*args, **kwargs)
                except Exception as e:
                    last_exc = e
            raise last_exc
        return wrapper
    return deco
```

